import { readFileSync } from "node:fs";
import { describe, expect, it } from "vitest";
import { ContentFetchError } from "@/core/ports/content-fetcher";
import { createPdfExtractor } from "./pdf-extractor";

// Samples generated by test/fixtures/pdf/make-samples.mjs (no network).
const fixture = (name: string) =>
  new Uint8Array(readFileSync(new URL(`../../test/fixtures/pdf/${name}`, import.meta.url)));

describe("PDF extractor (saved sample PDFs)", () => {
  const { extractPdf } = createPdfExtractor();

  it("reads a book's pages, title and top-level outline", async () => {
    const pdf = await extractPdf(fixture("book-with-outline.pdf"));

    expect(pdf.title).toBe("Streams in Practice");
    expect(pdf.pages).toHaveLength(6);
    expect(pdf.pages[2]).toContain("Each record gets an offset.");
    expect(pdf.pages[5]).toContain("Members of a group share the partitions.");
    // The nested "Offsets" entry under chapter 1 is not a chapter.
    expect(pdf.outline).toEqual([
      { title: "Chapter 1: Logs", page: 2 },
      { title: "Chapter 2: Partitions", page: 4 },
      { title: "Chapter 3: Consumer groups", page: 6 },
    ]);
  });

  it("returns no outline for a PDF without one", async () => {
    const pdf = await extractPdf(fixture("paper-no-outline.pdf"));

    expect(pdf.pages).toEqual(["Retries need backoff.", "Jitter spreads retries out.", "Idempotency makes retries safe."]);
    expect(pdf.outline).toEqual([]);
  });

  it("refuses a damaged file with a reason the learner can act on", async () => {
    await expect(extractPdf(new TextEncoder().encode("%PDF-1.4 not really"))).rejects.toThrow(ContentFetchError);
  });
});
